import copy
import unittest
from datetime import date

from tracker import overdue_tasks


class OverdueTasksTests(unittest.TestCase):
    today = date(2026, 1, 15)

    def test_unfinished_past_task_is_overdue(self):
        task = {"id": "a", "due": "2026-01-14", "completed": False}
        self.assertEqual(overdue_tasks([task], self.today), [task])

    def test_due_today_is_not_overdue(self):
        task = {"id": "b", "due": "2026-01-15", "completed": False}
        self.assertEqual(overdue_tasks([task], self.today), [])

    def test_completed_task_is_not_overdue(self):
        task = {"id": "c", "due": "2026-01-10", "completed": True}
        self.assertEqual(overdue_tasks([task], self.today), [])

    def test_future_task_is_not_overdue(self):
        task = {"id": "d", "due": "2026-01-16", "completed": False}
        self.assertEqual(overdue_tasks([task], self.today), [])

    def test_inputs_are_not_mutated(self):
        tasks = [
            {"id": "a", "due": "2026-01-14", "completed": False},
            {"id": "b", "due": "2026-01-15", "completed": False},
            {"id": "c", "due": "2026-01-10", "completed": True},
        ]
        snapshot = copy.deepcopy(tasks)
        overdue_tasks(tasks, self.today)
        self.assertEqual(tasks, snapshot)

    def test_unsorted_input_is_returned_oldest_first(self):
        tasks = [
            {"id": "newest", "due": "2026-01-14", "completed": False},
            {"id": "oldest", "due": "2026-01-10", "completed": False},
            {"id": "middle", "due": "2026-01-12", "completed": False},
        ]
        self.assertEqual(
            [task["id"] for task in overdue_tasks(tasks, self.today)],
            ["oldest", "middle", "newest"],
        )

    def test_equal_due_dates_keep_input_order(self):
        tasks = [
            {"id": "tie-first", "due": "2026-01-12", "completed": False},
            {"id": "earliest", "due": "2026-01-10", "completed": False},
            {"id": "tie-second", "due": "2026-01-12", "completed": False},
        ]
        self.assertEqual(
            [task["id"] for task in overdue_tasks(tasks, self.today)],
            ["earliest", "tie-first", "tie-second"],
        )


if __name__ == "__main__":
    unittest.main()
